{
  "title": "夜闯客栈",
  "scene": "你潜入了一家客栈，夜色中的客栈显得格外寂静。根据情报，这里藏着一个关于门派恩怨的重要线索。你轻轻地推开一扇半掩的门，发现屋内坐着一个老者，正借着烛光阅读古籍。老者的动作缓慢，似乎对周围环境并不关心。屋内还有一扇通往后院的小门，门缝中透出一丝微光。窗台上放着一包银两，显然是客栈掌柜的私藏。你该如何行动？",
  "goal": "找到并获取重要线索",
  "clue": "老者的动作缓慢，似乎对周围环境并不关心",
  "choices": [
    {
      "id": "A",
      "text": "直接询问老者",
      "outcome": "老者抬起头，眼中闪过一丝警觉。他冷冷地说道：‘你是谁？为何深夜来访？’显然，他并不信任你。你试图说服他，但老者始终保持警惕，最终没有透露任何信息。",
      "result": "fail",
      "next": "retry"
    },
    {
      "id": "B",
      "text": "从后门悄悄进入后院",
      "outcome": "你轻手轻脚地推开小门，进入后院。月光下，你发现一张被丢弃的纸条，上面写着关于门派恩怨的关键信息。虽然纸条有些残破，但你还是拼凑出了大部分内容。不过，返回屋内时，老者已经察觉到你的行动，对你产生了怀疑。",
      "result": "partial",
      "next": "next_level"
    },
    {
      "id": "C",
      "text": "利用轻功从窗外掠过",
      "outcome": "你施展轻功，轻盈地从窗外掠过，进入老者的房间。凭借老者的疏忽，你顺利找到了一本古籍，其中夹着一张记载门派恩怨的密信。你小心翼翼地取走密信，老者依然沉浸在阅读中，未察觉你的存在。",
      "result": "success",
      "next": "next_level"
    }
  ]
}
